import openpyxl, os
p=os.environ['OUT_XLSX']
wb=openpyxl.load_workbook(p)
ws=wb['Delete']
rows=[]
for r in range(1, ws.max_row+1):
    a=ws.cell(r,1).value
    b=ws.cell(r,2).value
    if r==1:
        rows.append((a,b))
    else:
        if b in ('STATIONERY','VEGETABLES'):
            continue
        rows.append((a,b))
# clear existing
for r in range(1, ws.max_row+1):
    for c in (1,2):
        ws.cell(r,c).value=None
for i,(a,b) in enumerate(rows, start=1):
    ws.cell(i,1).value=a
    ws.cell(i,2).value=b
wb.save(p)
print('done', len(rows))
